          <p className="text-xs font-extrabold text-yellow-600 uppercase tracking-widest mb-1">
            ¡Nuevo Logro Desbloqueado!
          </p>
          <h3 className="text-xl font-bold text-slate-800 truncate leading-tight">
            {badge.name}
